/**
 * MAIN VIDEO COMPOSITION
 *
 * Assembles all auto-discovered scenes in order using Remotion's <Series>.
 * DO NOT EDIT this file when adding scenes.
 */

import React from "react";
import { Series } from "remotion";
import { VIDEO } from "./design/tokens";
import { scenes } from "./scenes";

const FPS = VIDEO.fps;

export const Video: React.FC = () => {
  return (
    <>
      <Series>
        {scenes.map((scene) => (
          <Series.Sequence
            key={scene.config.id}
            durationInFrames={Math.round(scene.config.durationInSeconds * FPS)}
          >
            <scene.Component />
          </Series.Sequence>
        ))}
      </Series>

      {/*
       * Background music layer (uncomment and set your file):
       * import { Audio, staticFile } from "remotion";
       * <Audio src={staticFile("audio/bgm.mp3")} volume={0.1} />
       */}
    </>
  );
};
